// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована), вход не выполняется.
import { test, expect } from '@playwright/test';
import { prepareGuest, loginPopup, readRedirectAfterLogin, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Связь с владельцем — возврат после входа из попапа', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Выдача /search: «הצגת טלפון» на карточке → попап → SMS сохраняет возврат на эту карточку #083d10 ${device} @prod-safe`, async ({ page }) => {
      await prepareGuest(page);
      await page.goto('/search');

      const phoneBtn = page.getByRole('button', { name: 'הצגת טלפון' }).first();
      // выдача на проде под нагрузкой грузится и перестраивается 10–20 с
      await expect(phoneBtn).toBeVisible({ timeout: 30_000 });
      await phoneBtn.scrollIntoViewIfNeeded();
      // id объявления этой карточки — из ближайшей ссылки на /businessdetail в карточке кнопки
      const cardHref = await phoneBtn.evaluate((el) => {
        let c: HTMLElement | null = el as HTMLElement;
        for (let i = 0; i < 12 && c; i++) {
          c = c.parentElement;
          const a = c?.querySelector('a[href*="businessdetail"]');
          if (a) return a.getAttribute('href');
        }
        return null;
      });
      expect(cardHref, 'у карточки есть ссылка на объявление').not.toBeNull();
      const cardId = new URL(cardHref!, 'https://x').searchParams.get('id');
      expect(cardId).toBeTruthy();

      await phoneBtn.click();
      const popup = loginPopup(page);
      await expect(popup, 'открылся попап входа').toBeVisible(LOAD);
      await popup.getByRole('button', { name: /SMS/ }).click();

      await page.waitForURL((u) => u.pathname === '/auth' && u.searchParams.get('mode') === 'sms', LOAD);
      const saved = await readRedirectAfterLogin(page);
      expect(saved, 'redirectAfterLogin записан').not.toBeNull();
      const target = new URL(saved!, 'https://x');
      expect(target.pathname, 'возврат — на страницу объявления').toBe('/businessdetail');
      expect(target.searchParams.get('id'), 'возврат — на объявление этой карточки').toBe(cardId);
      expect(target.searchParams.get('contact'), 'с пометкой связи contact=1').toBe('1');
    });
  }
});
